'use strict'

const mineflayer = require('mineflayer')
const { pathfinder, Movements } = require('mineflayer-pathfinder')
const { makeBrain } = require('./brain')
const { findTarget, buildState, stateKey } = require('./perception')

const BEHAVIOURS = {
  fight: require('./behaviours/fight'),
  follow: require('./behaviours/follow'),
}

// Poll cadence when nobody is online: no JEV calls happen there, so waking
// up every 10 s just to re-scan the player list is plenty.
const IDLE_TICK_MS = 10000
const IDLE_LOG_MS = 60000

function createTicker({ bot, brain, tickMs = 1000, idleTickMs = IDLE_TICK_MS, followName = '' }) {
  const ctx = { lastGoalKey: '', movements: null }
  let inFlight = false
  let lastTargetPos = null
  let lastVisible = true
  let lastIdleLog = 0
  let lastStateKey = null
  let lastDecision = null

  function applyDecision(decision, target, state) {
    const handler = BEHAVIOURS[decision.action]
    if (typeof handler === 'function') {
      handler(bot, ctx, target, state)
    } else {
      if (ctx.lastGoalKey !== 'idle') bot.pathfinder.stop()
      ctx.lastGoalKey = 'idle'
    }
    if (ctx.movements) ctx.movements.allowSprinting = !!decision.sprint
    const dist = typeof state.distance_to_player === 'number' ? state.distance_to_player.toFixed(1) : 'none'
    console.log(`decision source=${decision.source} action=${decision.action} sprint=${decision.sprint} dist=${dist}`)
  }

  function scheduleNext(fast) {
    const t = setTimeout(() => { void tick() }, fast ? tickMs : idleTickMs)
    if (t && typeof t.unref === 'function') t.unref()
  }

  async function tick() {
    if (inFlight) { scheduleNext(lastVisible); return { decision: null, calledBrain: false } }
    inFlight = true
    let calledBrain = false
    try {
      const target = findTarget(bot, followName)
      lastVisible = !!target
      if (!target) {
        // Cost fix: nobody online => no brain call at all, decide idle
        // locally, stop once, and stay quiet (at most one line per minute).
        if (ctx.lastGoalKey !== 'idle') {
          bot.pathfinder.stop()
          ctx.lastGoalKey = 'idle'
        }
        lastTargetPos = null
        lastDecision = null
        lastStateKey = null
        const now = Date.now()
        if (now - lastIdleLog >= IDLE_LOG_MS) {
          lastIdleLog = now
          console.log('decision source=local-idle action=idle sprint=false dist=none')
        }
        return { decision: { action: 'idle', sprint: false, source: 'local-idle' }, calledBrain: false }
      }
      const state = buildState(bot, target, lastTargetPos)
      lastTargetPos = state._lastTargetPos
      // every-tick hooks (no body cost) go here
      const key = stateKey(state)
      let decision
      if (lastDecision && key === lastStateKey) {
        decision = lastDecision
      } else {
        decision = await brain.decide(state)
        calledBrain = true
        // A stub-fallback means JEV failed; don't cache it or JEV would
        // never be retried while the player stands still.
        if (decision.source !== 'stub-fallback') {
          lastStateKey = key
          lastDecision = decision
        }
      }
      applyDecision(decision, target, state)
      return { decision, calledBrain }
    } catch (err) {
      console.error(`tick error: ${err && err.message ? err.message : err}`)
      return { decision: null, calledBrain }
    } finally {
      inFlight = false
      scheduleNext(lastVisible)
    }
  }

  return {
    tick,
    start: () => scheduleNext(true),
    setMovements: (m) => { ctx.movements = m; bot.pathfinder.setMovements(m) },
    setFollow: (name) => { followName = name; ctx.lastGoalKey = '' },
    stop: () => {
      if (ctx.lastGoalKey !== 'idle') bot.pathfinder.stop()
      ctx.lastGoalKey = 'idle'
    }
  }
}

function main() {
  const rawTick = parseInt(process.env.BRAIN_TICK_MS || '1000', 10)
  const tickMs = Number.isFinite(rawTick) ? rawTick : 1000
  const brain = makeBrain(process.env)
  const bot = mineflayer.createBot({
    host: process.env.MC_HOST || 'mc',
    port: parseInt(process.env.MC_PORT || '25565', 10),
    username: process.env.BOT_USERNAME || 'IdkBot',
    auth: 'offline' // offline-mode server; see README for the online-mode note
  })
  bot.loadPlugin(pathfinder)
  const ticker = createTicker({ bot, brain, tickMs, followName: process.env.BOT_FOLLOW || '' })

  bot.once('spawn', () => {
    ticker.setMovements(new Movements(bot))
    console.log(`spawned as ${bot.username}`)
    ticker.start()
  })

  bot.on('chat', (username, message) => {
    if (username === bot.username) return
    const msg = message.toLowerCase().trim()
    if (msg === 'follow me') {
      ticker.setFollow(username)
      bot.chat(`Following ${username}`)
    } else if (msg === 'stop') {
      ticker.setFollow('')
      ticker.stop()
    }
  })

  function fatal(where, err) {
    console.error(`${where}: ${err && err.message ? err.message : err}`)
    process.exit(1)
  }
  bot.on('end', (reason) => fatal('end', reason || 'disconnected'))
  bot.on('error', (err) => fatal('error', err))
  bot.on('kicked', (reason) => fatal('kicked', reason))
}

if (require.main === module) main()

module.exports = { createTicker, BEHAVIOURS }

'use strict'

const HOSTILE_NAMES = new Set([
  'zombie', 'skeleton', 'spider', 'creeper', 'enderman', 'witch',
  'slime', 'husk', 'stray', 'drowned', 'pillager', 'phantom', 'blaze',
  'ghast', 'piglin_brute', 'hoglin', 'zoglin', 'cave_spider', 'silverfish',
  'endermite', 'vex', 'vindicator', 'evoker', 'ravager', 'warden', 'breeze',
  'bogged', 'creaking'
])

// Fight-candidate ranges: same numbers the brain criteria state (3nt.2) —
// a hostile counts for fight when within 8 blocks of the bot OR 6 of the player.
const FIGHT_RANGE_BOT = 8
const FIGHT_RANGE_PLAYER = 6

// ponytail: creepers are excluded from fight targets, not fled from —
// hitting one near the player makes it explode next to the player, and
// fleeing is out of scope.

// Dedup key: distance rounded to 1 block + same flags => reuse last decision,
// skip the JEV call. Staleness is at most half a block of travel.
function stateKey(state) {
  const d = state.distance_to_player
  const hd = state.hostile_distance
  return [
    typeof d === 'number' ? Math.round(d) : 'none',
    !!state.player_visible, !!state.player_moving,
    state.bot_health, state.bot_food, state.nearby_hostiles,
    typeof hd === 'number' ? Math.round(hd) : 'none',
    !!state.hostile_near_player
  ].join('|')
}

function findTarget(bot, followName) {
  if (followName) return (bot.players[followName] && bot.players[followName].entity) || null
  let best = null
  let bestDist = Infinity
  for (const player of Object.values(bot.players)) {
    if (!player.entity) continue
    if (player.username === bot.username) continue
    const d = bot.entity.position.distanceTo(player.entity.position)
    if (d < bestDist) {
      bestDist = d
      best = player.entity
    }
  }
  return best
}

function buildState(bot, target, lastTargetPos) {
  let distanceToPlayer = null
  let playerMoving = false
  let nextPos = null
  if (target) {
    distanceToPlayer = bot.entity.position.distanceTo(target.position)
    if (lastTargetPos) {
      playerMoving = target.position.distanceTo(lastTargetPos) > 0.1
    }
    nextPos = target.position.clone()
  }
  let nearbyHostiles = 0
  for (const entity of Object.values(bot.entities)) {
    if (entity.type === 'player' || !entity.position) continue
    const name = entity.name || entity.mobType || ''
    if (!HOSTILE_NAMES.has(name)) continue
    if (entity.position.distanceTo(bot.entity.position) < 16) nearbyHostiles++
  }
  let hostile = null
  let hostileDistance = null
  let hostilePlayerDistance = Infinity
  for (const entity of Object.values(bot.entities)) {
    if (entity.type === 'player' || !entity.position) continue
    const name = entity.name || entity.mobType || ''
    if (!HOSTILE_NAMES.has(name) || name === 'creeper') continue
    const dBot = entity.position.distanceTo(bot.entity.position)
    const dPlayer = target ? entity.position.distanceTo(target.position) : Infinity
    if (dBot > FIGHT_RANGE_BOT && dPlayer > FIGHT_RANGE_PLAYER) continue
    if (hostileDistance === null || dBot < hostileDistance) {
      hostile = entity
      hostileDistance = dBot
      hostilePlayerDistance = dPlayer
    }
  }
  const state = {
    distance_to_player: distanceToPlayer,
    player_visible: !!target,
    player_moving: playerMoving,
    bot_health: typeof bot.health === 'number' ? bot.health : 20,
    bot_food: typeof bot.food === 'number' ? bot.food : 20,
    nearby_hostiles: nearbyHostiles,
    hostile_distance: hostileDistance,
    hostile_near_player: hostile ? hostilePlayerDistance <= FIGHT_RANGE_PLAYER : false,
    hostile
  }
  state._lastTargetPos = nextPos
  return state
}

module.exports = { findTarget, buildState, stateKey, HOSTILE_NAMES }

'use strict'

const { describe, it } = require('node:test')
const assert = require('node:assert/strict')
const { createTicker, BEHAVIOURS } = require('../src/index')
const { buildState, stateKey } = require('../src/perception')
const { stubBrain } = require('../src/brain')
const fight = require('../src/behaviours/fight')

// Mock helpers use the same shape as tick.test.js.
function pos(x, y, z) {
  const p = {
    x, y, z,
    distanceTo: (q) => Math.hypot(p.x - q.x, p.y - q.y, p.z - q.z),
    clone() { return pos(p.x, p.y, p.z) }
  }
  return p
}

function mockBot() {
  const calls = { setGoal: 0, stop: 0, attack: 0, lookAt: 0, equip: 0 }
  const bot = {
    calls,
    username: 'IdkBot',
    players: {},
    entities: {},
    health: 20,
    food: 20,
    _items: [],
    _moving: false,
    entity: { position: pos(0, 64, 0) },
    inventory: { items: () => bot._items },
    equip: (item, dest) => { calls.equip++; calls.equipArgs = [item, dest] },
    lookAt: () => { calls.lookAt++ },
    attack: () => { calls.attack++ },
    pathfinder: {
      setGoal: () => { calls.setGoal++ },
      stop: () => { calls.stop++ },
      isMoving: () => bot._moving,
      setMovements: (m) => { calls.movements = m }
    },
    chat: () => {}
  }
  return bot
}

function playerEntity(x) {
  return { id: 7, position: pos(x, 64, 0) }
}

function mobEntity(id, name, x, opts = {}) {
  const p = pos(x, 64, 0)
  p.offset = (ox, oy, oz) => pos(p.x + ox, p.y + oy, p.z + oz)
  return { id, name, type: 'mob', position: p, height: 1.95, ...opts }
}

describe('perception hostile facts', () => {
  it('finds the nearest zombie: distance, entity, near-player flag', () => {
    const bot = mockBot()
    const zombie = mobEntity(1, 'zombie', 2)
    bot.entities = { 1: zombie }
    const state = buildState(bot, playerEntity(10), null)
    assert.equal(state.hostile_distance, 2)
    assert.equal(state.hostile, zombie)
    assert.equal(state.hostile_near_player, false) // zombie->player is 8 blocks
  })

  it('marks hostile_near_player when the mob is close to the player', () => {
    const bot = mockBot()
    bot.entities = { 1: mobEntity(1, 'zombie', 8) }
    const state = buildState(bot, playerEntity(10), null)
    assert.equal(state.hostile_distance, 8)
    assert.equal(state.hostile_near_player, true) // zombie->player is 2 blocks
  })

  it('ignores creepers for fight but still counts them as nearby', () => {
    const bot = mockBot()
    bot.entities = { 9: mobEntity(9, 'creeper', 2) }
    const state = buildState(bot, playerEntity(10), null)
    assert.equal(state.hostile_distance, null)
    assert.equal(state.hostile, null)
    assert.equal(state.hostile_near_player, false)
    assert.equal(state.nearby_hostiles, 1) // compatibility count kept
  })

  it('prefers the nearest non-creeper when a creeper is closer', () => {
    const bot = mockBot()
    const zombie = mobEntity(1, 'zombie', 5)
    bot.entities = { 9: mobEntity(9, 'creeper', 2), 1: zombie }
    const state = buildState(bot, playerEntity(10), null)
    assert.equal(state.hostile_distance, 5)
    assert.equal(state.hostile, zombie)
  })

  it('yields null hostile when nothing is in range', () => {
    const bot = mockBot()
    bot.entities = { 2: mobEntity(2, 'skeleton', 20) }
    const state = buildState(bot, playerEntity(30), null)
    assert.equal(state.hostile_distance, null)
    assert.equal(state.hostile, null)
    assert.equal(state.hostile_near_player, false)
  })

  it('stateKey changes when a hostile approaches', () => {
    const base = { distance_to_player: 10, player_visible: true, player_moving: false, bot_health: 20, bot_food: 20, nearby_hostiles: 1, hostile_distance: null, hostile_near_player: false }
    assert.notEqual(stateKey(base), stateKey({ ...base, hostile_distance: 4 }))
    assert.notEqual(stateKey({ ...base, hostile_distance: 7.4 }), stateKey({ ...base, hostile_distance: 4.2 }))
    assert.notEqual(stateKey({ ...base, hostile_distance: 4 }), stateKey({ ...base, hostile_distance: 4, hostile_near_player: true }))
  })
})

describe('fight behaviour', () => {
  it('swings once per call and sets the goal once at 2 blocks', () => {
    const bot = mockBot()
    const ctx = { lastGoalKey: '' }
    const state = { hostile: mobEntity(1, 'zombie', 2) }
    fight(bot, ctx, playerEntity(10), state)
    assert.equal(bot.calls.setGoal, 1)
    assert.equal(bot.calls.attack, 1)
    assert.equal(bot.calls.lookAt, 1)
    bot._moving = true
    fight(bot, ctx, playerEntity(10), state)
    assert.equal(bot.calls.setGoal, 1) // same target, already moving: no re-issue
    assert.equal(bot.calls.attack, 2) // one swing per tick
  })

  it('walks but does not swing at 6 blocks', () => {
    const bot = mockBot()
    fight(bot, { lastGoalKey: '' }, playerEntity(10), { hostile: mobEntity(1, 'zombie', 6) })
    assert.equal(bot.calls.setGoal, 1)
    assert.equal(bot.calls.attack, 0)
    assert.equal(bot.calls.lookAt, 0)
  })

  it('swing gate: attacks at exactly 3 blocks, not at 3.1', () => {
    const near = mockBot()
    fight(near, { lastGoalKey: '' }, playerEntity(10), { hostile: mobEntity(1, 'zombie', 3) })
    assert.equal(near.calls.attack, 1)
    const far = mockBot()
    fight(far, { lastGoalKey: '' }, playerEntity(10), { hostile: mobEntity(1, 'zombie', 3.1) })
    assert.equal(far.calls.attack, 0)
    assert.equal(far.calls.setGoal, 1)
  })

  it('equips the first sword once per target', () => {
    const bot = mockBot()
    const sword = { name: 'iron_sword' }
    bot._items = [{ name: 'dirt' }, sword]
    const ctx = { lastGoalKey: '' }
    const first = { hostile: mobEntity(1, 'zombie', 2) }
    fight(bot, ctx, playerEntity(10), first)
    assert.equal(bot.calls.equip, 1)
    assert.deepEqual(bot.calls.equipArgs, [sword, 'hand'])
    bot._moving = true
    fight(bot, ctx, playerEntity(10), first)
    assert.equal(bot.calls.equip, 1) // same target: no re-equip
    bot._moving = false
    fight(bot, ctx, playerEntity(10), { hostile: mobEntity(2, 'zombie', 2) })
    assert.equal(bot.calls.equip, 2) // new target: equip again
  })

  it('never equips without a sword in inventory', () => {
    const bot = mockBot()
    bot._items = [{ name: 'dirt' }]
    fight(bot, { lastGoalKey: '' }, playerEntity(10), { hostile: mobEntity(1, 'zombie', 2) })
    assert.equal(bot.calls.equip, 0)
    assert.equal(bot.calls.attack, 1) // fists are fine
  })

  it('stops once when the target is missing or dead', () => {
    const missing = mockBot()
    const ctx = { lastGoalKey: 'fight:1' }
    fight(missing, ctx, playerEntity(10), { hostile: null })
    assert.equal(missing.calls.stop, 1)
    assert.equal(missing.calls.attack, 0)
    assert.equal(missing.calls.setGoal, 0)
    fight(missing, ctx, playerEntity(10), { hostile: null })
    assert.equal(missing.calls.stop, 1) // already idle: no repeat stop
    const dead = mockBot()
    fight(dead, { lastGoalKey: 'fight:1' }, playerEntity(10), { hostile: mobEntity(1, 'zombie', 2, { isValid: false }) })
    assert.equal(dead.calls.stop, 1)
    assert.equal(dead.calls.attack, 0)
  })
})

describe('stub fight end-to-end', () => {
  it('zombie at 4 blocks -> fight; zombie gone -> follow', async () => {
    const bot = mockBot()
    bot.players = { Steve: { username: 'Steve', entity: playerEntity(10) } }
    bot.entities = { 1: mobEntity(1, 'zombie', 4) }
    const ticker = createTicker({ bot, brain: stubBrain, tickMs: 10, idleTickMs: 10 })
    const r1 = await ticker.tick()
    assert.equal(r1.decision.action, 'fight')
    assert.equal(r1.decision.source, 'stub')
    assert.equal(bot.calls.setGoal, 1)
    assert.equal(bot.calls.attack, 0) // 4 blocks: walking in, out of swing range
    delete bot.entities[1] // zombie dies
    const r2 = await ticker.tick()
    assert.equal(r2.decision.action, 'follow')
    assert.equal(r2.calledBrain, true) // hostile facts changed the state key
  })

  it('fight is wired in the dispatch table', () => {
    assert.equal(BEHAVIOURS.fight, fight)
  })
})

